function act(obs, mem) {
  var D2R = Math.PI / 180, R2D = 180 / Math.PI;
  function wrap(a) { a = (a + 180) % 360; if (a < 0) a += 360; return a - 180; }
  function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }
  var NA = 161, PHI0 = -160, DPH = 2, LIM = 4.5, RK = 0.5;
  var i, k, j;

  // ------------------------- init -------------------------
  if (!mem.init) {
    mem.init = 1;
    mem.P = []; mem.T = []; mem.B = []; mem.np = [];
    mem.dA = []; mem.cA = []; mem.sA = [];
    for (i = 0; i < NA; i++) { mem.dA.push(0); mem.cA.push(0); mem.sA.push(0); }
    mem.pk = 0.4; mem.pwrI = 0;
    mem.gw = 120; mem.turnI = 0; mem.rate = 0; mem.lastTurn = 0;
    mem.bias = 0;
    mem.aX = 0; mem.aY = 0; mem.aH = 0; mem.aN = 0; mem.aT = 0;
    mem.lx = obs.x; mem.ly = obs.y; mem.lh = obs.heading;
    mem.prevDirW = obs.heading; mem.theta = 0;
    mem.rec = 0; mem.recT = 0; mem.recSide = 1;
    mem.bestD = 1e9; mem.bestT = obs.t; mem.lastTgt = obs.targetIndex;
    mem.emN = 0; mem.vpk = 2.0; mem.tn = 0; mem.stopT = -99;
    mem.useBnd = (obs.x > -4 && obs.x < 44 && obs.y > -4 && obs.y < 44) ? 1 : 0;
  }

  var t = obs.t, x = obs.x, y = obs.y, sp = obs.speed || 0;
  var hR = obs.heading, tx = obs.targetX, ty = obs.targetY;
  var rays = obs.rays, rels = [-60, -30, 0, 30, 60];

  // new leg (checkpoint reached)
  if (obs.targetIndex !== mem.lastTgt) {
    mem.lastTgt = obs.targetIndex;
    mem.bestD = 1e9; mem.bestT = t; mem.rec = 0; mem.pwrI = 0;
    mem.B = [];
  }
  if (mem.useBnd && (x < -4 || x > 44 || y < -4 || y > 44)) mem.useBnd = 0;

  // ------------- motion estimate / compass bias -------------
  var dx = x - mem.lx, dy = y - mem.ly, dh = wrap(hR - mem.lh);
  mem.lx = x; mem.ly = y; mem.lh = hR;
  mem.rate = 0.5 * mem.rate + 0.5 * dh * 20;
  if (Math.abs(mem.lastTurn) > 0.3 && mem.rate * mem.lastTurn > 0 && Math.abs(mem.rate) < 320) {
    var g0 = mem.rate / mem.lastTurn;
    if (g0 > 25 && g0 < 500) mem.gw = 0.97 * mem.gw + 0.03 * g0;
  }
  mem.aX += dx; mem.aY += dy; mem.aH += hR; mem.aN++; mem.aT += Math.abs(dh);
  if (mem.aN > 5 && mem.aX * mem.aX + mem.aY * mem.aY > 4.6) {
    if (mem.aT / mem.aN < 1.4) {
      var b1 = wrap(mem.aH / mem.aN - Math.atan2(mem.aY, mem.aX) * R2D);
      var db = wrap(b1 - mem.bias);
      if (Math.abs(db) < 45) mem.bias = cl(mem.bias + 0.25 * db, -35, 35);
    }
    mem.aX = 0; mem.aY = 0; mem.aH = 0; mem.aN = 0; mem.aT = 0;
  }
  var hT = wrap(hR - mem.bias);

  // ---------------------- map update ----------------------
  for (i = 0; i < 5; i++) {
    var rr = rays[i];
    if (!(rr > 0.05) || rr > 9.8) continue;
    var aa = (hT + rels[i]) * D2R;
    mem.P.push(x + rr * Math.cos(aa), y + rr * Math.sin(aa), t);
  }
  if (mem.P.length > 4800) mem.P.splice(0, 900);

  // ----------------------- trail --------------------------
  mem.tn++;
  if (mem.tn % 3 === 0) {
    mem.T.push(x, y, t);
    if (mem.T.length > 900) mem.T.splice(0, 300);
  }

  // ------------------- local obstacle set -----------------
  var np = mem.np; np.length = 0;
  var P = mem.P, LR2 = 5.8 * 5.8, nearMin = 1e9;
  for (k = 0; k < P.length; k += 3) {
    var ex = P[k] - x, ey = P[k + 1] - y, d2 = ex * ex + ey * ey;
    if (d2 > LR2) continue;
    np.push(P[k], P[k + 1]);
    var d1 = Math.sqrt(d2) - RK;
    if (d1 < nearMin) nearMin = d1;
  }
  if (nearMin < 0) nearMin = 0;

  // clearance along a world heading (metres, capped at lim)
  function clrAt(aDeg, lim) {
    var a = aDeg * D2R, ux = Math.cos(a), uy = Math.sin(a), best = lim, qq;
    for (var m = 0; m < np.length; m += 2) {
      var ex = np[m] - x, ey = np[m + 1] - y, d2 = ex * ex + ey * ey;
      if (d2 > (lim + RK) * (lim + RK)) continue;
      if (d2 < RK * RK) return 0;
      var bb = ex * ux + ey * uy;
      if (bb <= 0) continue;
      var disc = bb * bb - (d2 - RK * RK);
      if (disc <= 0) continue;
      var tt = bb - Math.sqrt(disc);
      if (tt < best) { best = tt; if (best <= 0) return 0; }
    }
    if (mem.useBnd) {
      var tb = lim;
      if (ux < -0.001) { qq = (x - 0.55) / (-ux); if (qq < tb) tb = qq; }
      if (ux > 0.001) { qq = (39.45 - x) / ux; if (qq < tb) tb = qq; }
      if (uy < -0.001) { qq = (y - 0.55) / (-uy); if (qq < tb) tb = qq; }
      if (uy > 0.001) { qq = (39.45 - y) / uy; if (qq < tb) tb = qq; }
      if (tb < 0) tb = 0;
      if (tb < best) best = tb;
    }
    return best;
  }

  // ------------------- clearance field -------------------
  var dA = mem.dA, cA = mem.cA, sA = mem.sA;
  for (i = 0; i < NA; i++) dA[i] = clrAt(hT + PHI0 + i * DPH, LIM);
  for (i = 0; i < NA; i++) {
    var mn = LIM;
    for (j = i - 2; j <= i + 2; j++) if (j >= 0 && j < NA && dA[j] < mn) mn = dA[j];
    cA[i] = mn;
  }

  // ------------------- target direction ------------------
  var tgx = tx - x, tgy = ty - y, tdist = Math.sqrt(tgx * tgx + tgy * tgy);
  if (tdist > 0.35) mem.theta = wrap(Math.atan2(tgy, tgx) * R2D - hT);
  var theta = mem.theta;

  // ----------------------- scoring -----------------------
  for (i = 0; i < NA; i++) {
    var phi = PHI0 + i * DPH;
    var sc = 1.5 * Math.cos((phi - theta) * D2R);
    sc += 0.4 * Math.min(cA[i], 1.6) / 1.6;
    sc += 0.4 * Math.cos((phi + hT - mem.prevDirW) * D2R);
    if (dA[i] < 0.7) sc -= 8;
    else if (dA[i] < 1.15) sc -= 1.5;
    sA[i] = sc;
  }
  // discourage retracing recent path
  var TT = mem.T;
  for (k = 0; k < TT.length; k += 3) {
    var age = t - TT[k + 2];
    if (age < 0.5 || age > 8) continue;
    var ex = TT[k] - x, ey = TT[k + 1] - y, dd = Math.sqrt(ex * ex + ey * ey);
    if (dd > 3.2 || dd < 0.5) continue;
    var bp = wrap(Math.atan2(ey, ex) * R2D - hT);
    var half = R2D * Math.asin(cl(0.8 / dd, 0, 1)) + 3;
    var w = 0.45 * (1 - age / 8);
    var i0 = Math.max(0, Math.ceil((bp - half - PHI0) / DPH));
    var i1 = Math.min(NA - 1, Math.floor((bp + half - PHI0) / DPH));
    for (i = i0; i <= i1; i++) sA[i] -= w;
  }
  // discourage dead-end pockets found earlier
  var BB = mem.B;
  for (k = 0; k < BB.length; k += 3) {
    var age = t - BB[k + 2];
    if (age > 45) continue;
    var ex = BB[k] - x, ey = BB[k + 1] - y, dd = Math.sqrt(ex * ex + ey * ey);
    if (dd > 6 || dd < 1) continue;
    var bp = wrap(Math.atan2(ey, ex) * R2D - hT);
    var half = R2D * Math.asin(cl(1.9 / dd, 0, 1)) + 5;
    var w = 1.6 * (1 - age / 45);
    var i0 = Math.max(0, Math.ceil((bp - half - PHI0) / DPH));
    var i1 = Math.min(NA - 1, Math.floor((bp + half - PHI0) / DPH));
    for (i = i0; i <= i1; i++) sA[i] -= w;
  }

  // ---------------------- selection ----------------------
  var bestI = 0, bestS = -1e9, maxD = 0, maxI = 0;
  for (i = 0; i < NA; i++) {
    if (sA[i] > bestS) { bestS = sA[i]; bestI = i; }
    if (dA[i] > maxD) { maxD = dA[i]; maxI = i; }
  }
  if (maxD < 0.7) bestI = maxI;
  var phi = PHI0 + bestI * DPH;
  mem.prevDirW = hT + phi;

  // ------------------- speed target ----------------------
  if (sp > mem.vpk) mem.vpk = sp; else mem.vpk *= 0.999;
  var vOpen = cl(0.92 * mem.vpk, 1.3, 3.4);
  var f1 = cl((dA[bestI] - 0.5) / 2.2, 0, 1);
  var f2 = cl((cA[bestI] - 0.3) / 1.6, 0, 1);
  var f3 = cl((nearMin - 0.15) / 1.1, 0, 1);
  var vT = vOpen * cl(Math.min(f1, Math.min(f2, f3)), 0.22, 1);
  vT *= cl(1 - 0.4 * Math.abs(phi) / 110, 0.55, 1);
  if (tdist < 1.5) vT = Math.min(vT, 0.25 + 0.45 * tdist);

  // ----------------------- control -----------------------
  var turn = 0, v = 0;
  if (Math.abs(phi) > 100 && nearMin > 1.7 && tdist > 1.3) {
    turn = (phi > 0 ? 1 : -1) * cl(Math.abs(phi) / 45, 0.5, 1);
    v = 0.02;
    mem.pwrI *= 0.9;
  } else {
    var e = phi;
    if (Math.abs(e) < 25) mem.turnI = cl(mem.turnI + 0.0012 * e, -0.22, 0.22);
    var dr = cl(1.9 * e, -180, 180);
    turn = cl(dr / mem.gw + mem.turnI, -1, 1);
    if (Math.abs(e) > 4 && Math.abs(turn) < 0.13) turn = e > 0 ? 0.13 : -0.13;
    mem.pwrI = cl(mem.pwrI + 0.05 * cl(vT - sp, -0.6, 0.6), -0.35, 0.35);
    v = cl(mem.pk * vT + mem.pwrI + 0.3 * (vT - sp), -0.7, 1);
  }

  // live-ray repulsion (fresh safety bias)
  var rep = 0;
  for (i = 0; i < 5; i++) {
    var rr = rays[i]; if (!(rr > 0)) rr = 10;
    if (rr < 2.2) rep -= (2.2 - rr) * Math.sin(rels[i] * D2R);
  }
  turn = cl(turn + cl(rep / 1.2, -1, 1) * 0.45, -1, 1);

  // --------------------- emergency -----------------------
  var r0 = rays[0] > 9.5 ? 10 : rays[0], r1 = rays[1] > 9.5 ? 10 : rays[1];
  var r2 = rays[2] > 9.5 ? 10 : rays[2], r3 = rays[3] > 9.5 ? 10 : rays[3];
  var r4 = rays[4] > 9.5 ? 10 : rays[4];
  var crit = (r2 < 0.85 || r1 < 0.55 || r3 < 0.55 || r0 < 0.45 || r4 < 0.45);
  if (crit) mem.emN++; else mem.emN = 0;
  if (crit && (mem.emN >= 2 || r2 < 0.4 || r1 < 0.3 || r3 < 0.3)) {
    var side = (r3 + r4 > r1 + r0) ? 1 : ((r3 + r4 < r1 + r0) ? -1 : (theta >= 0 ? 1 : -1));
    turn = side * 0.9;
    if (r2 < 0.85) {
      var rearC = clrAt(hT + 180, 3);
      v = -0.55 * cl(rearC / 1.2, 0, 1);
    } else {
      v = Math.min(v, 0.35);
    }
  }

  // ------------------ stuck recovery ---------------------
  if (tdist < mem.bestD - 0.5) { mem.bestD = tdist; mem.bestT = t; }
  if (Math.abs(sp) < 0.15) { if (mem.stopT < -50) mem.stopT = t; } else mem.stopT = -99;
  var stuck = (t - mem.bestT > 5) || (mem.stopT > -50 && t - mem.stopT > 2.5);
  if (stuck && mem.rec === 0) {
    mem.rec = 1; mem.recT = t;
    mem.recSide = (r3 + r4 >= r1 + r0) ? 1 : -1;
    if (tdist > 3.5) {
      mem.B.push(x, y, t);
      if (mem.B.length > 300) mem.B.splice(0, 3);
    }
    mem.bestT = t; mem.stopT = -99; mem.emN = 0;
  }
  if (mem.rec === 1) {
    var rearC = clrAt(hT + 180, 3);
    v = -0.55 * cl(rearC / 1.3, 0, 1);
    turn = mem.recSide * 0.3;
    if (t - mem.recT > 1.1) { mem.rec = 2; mem.recT = t; }
  } else if (mem.rec === 2) {
    v = 0.02; turn = mem.recSide * 0.85;
    if (t - mem.recT > 0.8) {
      mem.rec = 0; mem.bestT = t; mem.stopT = -99;
      mem.prevDirW = hT + mem.recSide * 45;
    }
  }

  // ------------------------ mix --------------------------
  if (turn > 1) turn = 1; if (turn < -1) turn = -1;
  var vm = 1 - Math.abs(turn);
  v = cl(v, -vm, vm);
  mem.lastTurn = turn;
  if (Math.abs(v) > 0.25 && sp > 0.25 && Math.abs(turn) < 0.35) {
    var est = v / sp;
    if (est > 0.03 && est < 3) mem.pk = 0.985 * mem.pk + 0.015 * est;
  }
  return { left: cl(v - turn, -1, 1), right: cl(v + turn, -1, 1) };
}

function act(obs, mem) {
  var D2R = Math.PI / 180, R2D = 180 / Math.PI;
  function wrap(a) { a = (a + 180) % 360; if (a < 0) a += 360; return a - 180; }
  function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function nz(v, d) { return (typeof v === 'number' && v === v) ? v : d; }

  if (!mem.i) {
    mem.i = 1;
    mem.lx = nz(obs.x, 0); mem.ly = nz(obs.y, 0);
    mem.lh = nz(obs.heading, 0);
    mem.hE = mem.lh;
    mem.tR = 0; mem.pT = 0;
    mem.bD = 1e9; mem.bT = nz(obs.t, 0);
    mem.rec = 0; mem.rT = 0; mem.rP = 0; mem.rS = 1;
    mem.lI = obs.targetIndex;
    mem.sT = 0; mem.rN = 0;
    mem.bad = [];
  }

  var t = nz(obs.t, 0), x = nz(obs.x, mem.lx), y = nz(obs.y, mem.ly);
  var sp = nz(obs.speed, 0);
  var h = nz(obs.heading, mem.lh);
  var tx = obs.targetX, ty = obs.targetY;
  var rays = obs.rays || [10, 10, 10, 10, 10];

  if (obs.targetIndex !== mem.lI) {
    mem.lI = obs.targetIndex;
    mem.bD = 1e9; mem.bT = t; mem.rec = 0; mem.sT = 0;
    mem.bad = [];
  }

  var dx = x - mem.lx, dy = y - mem.ly;
  var disp = Math.sqrt(dx * dx + dy * dy);
  mem.lx = x; mem.ly = y;
  var dh = wrap(h - mem.lh);
  mem.tR = 0.6 * mem.tR + 0.4 * dh * 20;
  mem.lh = h;

  if (disp > 0.03) {
    var gpsB = Math.atan2(dy, dx) * R2D;
    var errF = wrap(gpsB - mem.hE), errB = wrap(gpsB + 180 - mem.hE);
    mem.hE = wrap(mem.hE + 0.2 * ((Math.abs(errF) < Math.abs(errB)) ? errF : errB));
  } else {
    mem.hE = wrap(mem.hE + mem.tR * 0.05);
  }

  var tgx = nz(tx, x) - x, tgy = nz(ty, y) - y;
  var tgD = Math.sqrt(tgx * tgx + tgy * tgy);
  var tgB = tgD < 0.5 ? 0 : wrap(Math.atan2(tgy, tgx) * R2D - mem.hE);

  var r = [];
  for (var i = 0; i < 5; i++) {
    var rv = nz(rays[i], 10);
    r[i] = rv > 9.5 ? 10 : cl(rv - 0.2, 0.05, 10);
  }

  var pTurn = 0.015 * tgB;
  var dTurn = -0.008 * mem.tR;

  var aF = 0, SAFE = 3.5;
  if (r[0] < SAFE) aF += (SAFE - r[0]) * 0.5;
  if (r[1] < SAFE) aF += (SAFE - r[1]) * 1.0;
  if (r[3] < SAFE) aF -= (SAFE - r[3]) * 1.0;
  if (r[4] < SAFE) aF -= (SAFE - r[4]) * 0.5;
  if (r[2] < SAFE) {
    aF += ((r[3] + r[4] > r[1] + r[0]) ? 1 : -1) * (SAFE - r[2]) * 3.0;
  }
  var aTurn = 0.020 * aF;

  while (mem.bad.length >= 3 && t - mem.bad[2] > 45) mem.bad.splice(0, 3);
  for (var k = 0; k < mem.bad.length; k += 3) {
    if (t - mem.bad[k + 2] > 45) continue;
    var bx = mem.bad[k] - x, by = mem.bad[k + 1] - y;
    var bd = Math.sqrt(bx * bx + by * by);
    if (bd < 6 && bd > 0.5) {
      var bAng = wrap(Math.atan2(by, bx) * R2D - mem.hE);
      if (Math.abs(bAng) < 50) {
        aTurn += (bAng > 0 ? -1 : 1) * 0.25 * (1 - bd / 6);
      }
    }
  }

  var turn = pTurn + dTurn + aTurn;

  var sSide = (r[3] + r[4] > r[1] + r[0]) ? 1 : -1;
  var critR = 1.5, danger = 0;
  if (r[0] < critR) danger += (critR - r[0]) * 2;
  if (r[1] < critR) danger += (critR - r[1]) * 3;
  if (r[2] < critR) danger += (critR - r[2]) * 4 * sSide;
  if (r[3] < critR) danger -= (critR - r[3]) * 3;
  if (r[4] < critR) danger -= (critR - r[4]) * 2;
  if (Math.abs(danger) > 0.3) turn = cl(danger * 0.5, -0.7, 0.7);

  turn = mem.pT + cl(turn - mem.pT, -0.07, 0.07);
  mem.pT = turn;
  turn = cl(turn, -0.7, 0.7);

  var minR = Math.min(r[0], r[1], r[2], r[3], r[4]);
  var v = cl((minR - 0.6) / 2.5, 0.05, 0.9);
  v *= cl(1 - 1.5 * Math.abs(turn), 0.25, 1);
  if (tgD < 2) v = Math.min(v, cl(0.3 * tgD, 0.05, 0.5));
  if (minR < 0.8) v = Math.min(v, 0.1);

  if (tgD < mem.bD - 0.3) { mem.bD = tgD; mem.bT = t; }
  if (disp < 0.003) mem.sT += 0.05;
  else mem.sT = Math.max(0, mem.sT - 0.1);

  if ((t - mem.bT > 4.0 || mem.sT > 3.0) && mem.rec === 0) {
    mem.rec = 1; mem.rP = 0; mem.rT = t;
    mem.rN = (mem.rN + 1) % 4;
    mem.rS = (mem.rN === 2) ? -sSide : sSide;
    mem.bad.push(x, y, t);
    if (mem.bad.length > 90) mem.bad.splice(0, 3);
    mem.bT = t; mem.sT = 0;
  }

  if (mem.rec > 0) {
    if (mem.rP === 0) {
      v = -0.5;
      turn = mem.rS * 0.1;
      if (t - mem.rT > 1.2) { mem.rP = 1; mem.rT = t; }
    } else {
      v = 0.1;
      turn = mem.rS * (0.5 + mem.rN * 0.15);
      if (t - mem.rT > 0.8 + mem.rN * 0.15) {
        mem.rec = 0; mem.bT = t; mem.sT = 0; mem.pT = turn;
      }
    }
  }

  turn = cl(turn, -1, 1);
  var maxV = 1 - 0.6 * Math.abs(turn);
  v = cl(v, -maxV, maxV);
  return { left: cl(v - turn, -1, 1), right: cl(v + turn, -1, 1) };
}

function act(obs, mem) {
  var D2R = Math.PI / 180, R2D = 180 / Math.PI;
  function wrap(a) { a = (a + 180) % 360; if (a < 0) a += 360; return a - 180; }
  function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function num(v, d) { return (typeof v === 'number' && v === v) ? v : d; }

  if (!mem.i) {
    mem.i = 1;
    mem.h = num(obs.heading, 0);
    mem.bF = 0;
    mem.turn = 0;
    mem.bestD = 1e9;
    mem.bestT = num(obs.t, 0);
    mem.rec = 0;
    mem.recT = 0;
    mem.recDir = 1;
    mem.lastIdx = obs.targetIndex;
    mem.px = num(obs.x, 0);
    mem.py = num(obs.y, 0);
    mem.lastTC = 0;
    mem.tIP = 0;
  }

  var t = num(obs.t, 0);
  var x = num(obs.x, mem.px), y = num(obs.y, mem.py);
  var sp = num(obs.speed, 0);
  var hRaw = num(obs.heading, mem.h);
  var rays = obs.rays || [10, 10, 10, 10, 10];
  var tx = num(obs.targetX, x), ty = num(obs.targetY, y);

  if (obs.targetIndex !== mem.lastIdx) {
    mem.lastIdx = obs.targetIndex;
    mem.bestD = 1e9;
    mem.bestT = t;
    mem.rec = 0;
    mem.bF = 0;
    mem.tIP = 0;
  }

  var r = [];
  for (var i = 0; i < 5; i++) {
    var rv = num(rays[i], 10);
    r[i] = (rv > 9.5) ? 10 : Math.max(rv, 0.05);
  }
  var minR = Math.min(r[0], r[1], r[2], r[3], r[4]);
  var lS = r[3] + r[4], rS = r[0] + r[1];

  // Heading: motor integration + GPS correction + slow compass
  mem.h = wrap(mem.h + 230 * mem.lastTC * 0.05);
  var dx = x - mem.px, dy = y - mem.py;
  mem.px = x; mem.py = y;
  if (Math.sqrt(dx * dx + dy * dy) > 0.04 && Math.abs(sp) > 0.15) {
    var gpsB = Math.atan2(dy, dx) * R2D;
    if (sp < -0.05) gpsB = wrap(gpsB + 180);
    var gErr = wrap(gpsB - mem.h);
    if (Math.abs(gErr) < 60) mem.h = wrap(mem.h + 0.2 * gErr);
  }
  mem.h = wrap(mem.h + 0.05 * wrap(hRaw - mem.h));

