    speed: speedAbs
  });

  while (mem.motion.length > 42) {
    mem.motion.shift();
  }

  if (
    tick % 16 === 0 &&
    mem.motion.length >= 26
  ) {
    var motionN = 26;
    var motionStart = mem.motion.length - motionN;
    var firstMotion = mem.motion[motionStart];
    var lastMotion = mem.motion[mem.motion.length - 1];

    var mdx = lastMotion.x - firstMotion.x;
    var mdy = lastMotion.y - firstMotion.y;
    var netMotion = Math.sqrt(mdx * mdx + mdy * mdy);

    var pathMotion = 0;
    var hCos = 0;
    var hSin = 0;
    var sumBase = 0;
    var sumTurn = 0;
    var sumSpeed = 0;

    for (var mi = 0; mi < motionN; mi++) {
      var mp = mem.motion[motionStart + mi];
      var mh = mp.h * PI / 180;

      hCos += Math.cos(mh);
      hSin += Math.sin(mh);
      sumBase += mp.base;
      sumTurn += Math.abs(mp.turn);
      sumSpeed += mp.speed;

      if (mi > 0) {
        var prevMp = mem.motion[motionStart + mi - 1];
        var qx = mp.x - prevMp.x;
        var qy = mp.y - prevMp.y;
        pathMotion += Math.sqrt(qx * qx + qy * qy);
      }
    }

    var avgBase = sumBase / motionN;
    var avgTurn = sumTurn / motionN;
    var avgSpeed = sumSpeed / motionN;
    var straightness =
      netMotion / Math.max(pathMotion, 0.01);

    if (
      avgBase > 0.28 &&
      avgTurn < 0.085 &&
      avgSpeed > 0.28 &&
      netMotion > 0.45 &&
      pathMotion > 0.55 &&
      straightness > 0.78
    ) {
      var motionHeading =
        Math.atan2(mdy, mdx) * 180 / PI;

      var compassHeading =
        Math.atan2(hSin, hCos) * 180 / PI;

      var measuredBias =
        wrapDeg(motionHeading - compassHeading);

      if (Math.abs(measuredBias) < 65) {
        var biasError = wrapDeg(measuredBias - mem.bias);

        if (Math.abs(biasError) < 55) {
          mem.bias += clamp(
            biasError * 0.018,
            -0.70,
            0.70
          );
          mem.bias = clamp(mem.bias, -35, 35);
        }
      }
    }
  }

  var raw = [];
  var ray = [];

  for (var ri = 0; ri < 5; ri++) {
    var rv = 10;

    if (obs.rays && finite(obs.rays[ri])) {
      rv = obs.rays[ri];
    }

    if (ri === 2 && finite(obs.distanceAhead)) {
      rv = Math.min(rv, obs.distanceAhead);
    }

    rv = clamp(rv, 0, 10);
    raw[ri] = rv;

    var rf = finite(mem.rayFilter[ri])
      ? mem.rayFilter[ri]
      : rv;

    if (!mem.scanSeen) {
      rf = rv;
    } else if (rv < rf) {
      rf = rf * 0.40 + rv * 0.60;
    } else {
      rf = Math.min(10, rf + 0.28);
    }

    mem.rayFilter[ri] = clamp(rf, 0, 10);

    ray[ri] = clamp(
      Math.min(rv, mem.rayFilter[ri] + 0.35),
      0,
      10
    );
  }

  mem.scanSeen = true;

  var targetIndexGiven = finite(obs.targetIndex);
  var targetIndex = targetIndexGiven
    ? Math.max(0, Math.floor(obs.targetIndex))
    : (
      finite(mem.targetIndex) && mem.targetIndex >= 0
        ? mem.targetIndex
        : 0
    );

  var tx = finite(obs.targetX) ? obs.targetX : NaN;
  var ty = finite(obs.targetY) ? obs.targetY : NaN;

  if (
    (!finite(tx) || !finite(ty)) &&
    obs.targets &&
    typeof obs.targets.length === "number" &&
    obs.targets[targetIndex] !== undefined
  ) {
    var targetEntry = obs.targets[targetIndex];

    if (Array.isArray(targetEntry)) {
      if (!finite(tx) && finite(targetEntry[0])) {
        tx = targetEntry[0];
      }
      if (!finite(ty) && finite(targetEntry[1])) {
        ty = targetEntry[1];
      }
    } else if (targetEntry) {
      if (!finite(tx) && finite(targetEntry.x)) {
        tx = targetEntry.x;
      }
      if (!finite(ty) && finite(targetEntry.y)) {
        ty = targetEntry.y;
      }
    }
  }

  if (
    (!finite(tx) || !finite(ty)) &&
    finite(obs.goalX) &&
    finite(obs.goalY)
  ) {
    if (!finite(tx)) tx = obs.goalX;
    if (!finite(ty)) ty = obs.goalY;
  }

  if (
    (!finite(tx) || !finite(ty)) &&
    mem.haveTargetCoords
  ) {
    tx = mem.lastTargetX;
    ty = mem.lastTargetY;
  }

  if (!finite(tx) || !finite(ty)) {
    return drive(0, 0, true);
  }

  var coordinateJump = false;

  if (
    mem.haveTargetCoords &&
    mem.targetIndex === targetIndex &&
    finite(mem.lastTargetX) &&
    finite(mem.lastTargetY)
  ) {
    var cdx = tx - mem.lastTargetX;
    var cdy = ty - mem.lastTargetY;

    coordinateJump =
      Math.sqrt(cdx * cdx + cdy * cdy) > 3.5;
  }

  var targetKey = targetIndexGiven
    ? "i:" + String(targetIndex)
    : (
      "p:" +
      String(Math.round(tx * 2)) +
      ":" +
      String(Math.round(ty * 2))
    );

  var targetChanged =
    mem.targetKey === null ||
    targetKey !== mem.targetKey ||
    coordinateJump;

  if (targetChanged) {
    mem.targetKey = targetKey;
    mem.targetIndex = targetIndex;
    mem.lastTargetX = tx;
    mem.lastTargetY = ty;
    mem.haveTargetCoords = true;

    mem.txSmooth = tx;
    mem.tySmooth = ty;

    mem.mode = "go";
    mem.side = 0;
    mem.followTicks = 0;
    mem.clearTicks = 0;
    mem.blockedTicks = 0;
    mem.sideSwitches = 0;

    mem.recoverPhase = 0;
    mem.recoverTicks = 0;
    mem.recoverSwitched = false;

    mem.path = [];
    mem.loopHits = 0;
    mem.lastLoopTick = -100000;
    mem.recoverCount = 0;

    mem.stuck = 0;
    mem.cooldown = 20;
  } else {
    mem.lastTargetX = tx;
    mem.lastTargetY = ty;

    if (!finite(mem.txSmooth)) mem.txSmooth = tx;
    if (!finite(mem.tySmooth)) mem.tySmooth = ty;

    mem.txSmooth =
      mem.txSmooth * 0.82 + tx * 0.18;

    mem.tySmooth =
      mem.tySmooth * 0.82 + ty * 0.18;
  }

  if (mem.cooldown > 0) {
    mem.cooldown -= 1;
  }

  var gx = mem.txSmooth;
  var gy = mem.tySmooth;

  var gdx = gx - mem.px;
  var gdy = gy - mem.py;
  var dist = Math.sqrt(gdx * gdx + gdy * gdy);

  if (targetChanged || !finite(mem.distFilt)) {
    mem.distFilt = dist;
  } else {
    mem.distFilt =
      mem.distFilt * 0.80 + dist * 0.20;
  }

  var controlDist =
    finite(mem.distFilt) ? mem.distFilt : dist;

  var bearing = dist > 0.05
    ? Math.atan2(gdy, gdx) * 180 / PI
    : wrapDeg(heading + mem.bias);

  if (targetChanged) {
    mem.goalAngle = bearing;
    mem.bestDist = controlDist;
    mem.bestTick = tick;
  } else {
    var bearingDelta =
      wrapDeg(bearing - mem.goalAngle);

    mem.goalAngle = wrapDeg(
      mem.goalAngle +
      clamp(bearingDelta * 0.22, -13, 13)
    );
  }

  var effectiveHeading =
    wrapDeg(heading + (finite(mem.bias) ? mem.bias : 0));

  var goalError =
    wrapDeg(mem.goalAngle - effectiveHeading);

  var absGoal = Math.abs(goalError);

  if (controlDist < mem.bestDist - 0.12) {
    mem.bestDist = controlDist;
    mem.bestTick = tick;
    mem.loopHits = 0;
  }

  var leftOpen =
    0.70 * ray[3] + 0.30 * ray[4];

  var rightOpen =
    0.70 * ray[1] + 0.30 * ray[0];

  function pathOpen(direction) {
    return direction > 0 ? leftOpen : rightOpen;
  }

  function risk(distance, safeDistance) {
    return clamp(
      (safeDistance - distance) /
      Math.max(0.1, safeDistance),
      0,
      1
    );
  }

  var rightThreat =
    0.78 * risk(ray[1], 1.70) +
    0.34 * risk(ray[0], 1.10);

  var leftThreat =
    0.78 * risk(ray[3], 1.70) +
    0.34 * risk(ray[4], 1.10);

  var frontDist = ray[2];

  if (ray[2] < 4.6 && ray[1] < 2.3) {
    frontDist = Math.min(frontDist, ray[1] + 0.75);
  }

  if (ray[2] < 4.6 && ray[3] < 2.3) {
    frontDist = Math.min(frontDist, ray[3] + 0.75);
  }

  if (
    ray[2] < 3.5 &&
    ray[1] < 1.55 &&
    ray[3] < 1.55
  ) {
    frontDist = Math.min(
      frontDist,
      Math.min(ray[1], ray[3]) + 0.68
    );
  }

  var frontTrigger =
    3.0 + clamp(mem.speedFilt * 0.52, 0, 0.80);

  var sideBlock =
    ray[1] < 0.82 ||
    ray[3] < 0.82;

  var outerClose =
    (ray[0] < 0.62 && ray[1] < 1.45) ||
    (ray[4] < 0.62 && ray[3] < 1.45);

  var obstacleAhead =
    frontDist < frontTrigger ||
    raw[2] < 0.95 ||
    (
      ray[2] < 2.75 &&
      (ray[1] < 1.60 || ray[3] < 1.60)
    ) ||
    (
      sideBlock &&
      frontDist < 3.9
    ) ||
    outerClose;

  var boxed =
    frontDist < 1.38 &&
    ray[1] < 1.02 &&
    ray[3] < 1.02;

  var panic =
    frontDist < 0.78 ||
    raw[2] < 0.58 ||
    (
      raw[1] < 0.30 &&
      frontDist < 1.55
    ) ||
    (
      raw[3] < 0.30 &&
      frontDist < 1.55
    ) ||
    (
      ray[1] < 0.54 &&
      ray[3] < 0.54 &&
      frontDist < 1.72
    );

  var boundaryDistance = Math.min(
    mem.px,
    40 - mem.px,
    mem.py,
    40 - mem.py
  );

  if (!finite(boundaryDistance)) {
    boundaryDistance = 20;
  }

  var inwardX = 0;
  var inwardY = 0;

  if (mem.px < 2.2) inwardX += 1;
  if (mem.px > 37.8) inwardX -= 1;
  if (mem.py < 2.2) inwardY += 1;
  if (mem.py > 37.8) inwardY -= 1;

  var boundaryTurn = 0;
  var boundarySlow = 0;

  if (
    boundaryDistance < 2.8 &&
    (inwardX !== 0 || inwardY !== 0)
  ) {
    var inwardAngle =
      Math.atan2(inwardY, inwardX) * 180 / PI;

    boundaryTurn = clamp(
      wrapDeg(inwardAngle - effectiveHeading) * 0.0042,
      -0.38,
      0.38
    );

    boundarySlow = clamp(
      (2.8 - boundaryDistance) / 2.0,
      0,
      1
    );
  }

  var repeatedPosition = false;

  if (tick % 15 === 0) {
    for (var hi = 0; hi < mem.path.length; hi++) {
      var oldPoint = mem.path[hi];
      var age = tick - oldPoint.tick;

      if (age > 90 && age < 1000) {
        var pdx = mem.px - oldPoint.x;
        var pdy = mem.py - oldPoint.y;
        var pd = Math.sqrt(pdx * pdx + pdy * pdy);

        if (
          pd < 0.70 &&
          controlDist > oldPoint.dist - 0.18
        ) {
          repeatedPosition = true;
          break;
        }
      }
    }

    if (
      repeatedPosition &&
      tick - mem.lastLoopTick > 45
    ) {
      mem.lastLoopTick = tick;
      mem.loopHits += 1;
    }

    mem.path.push({
      x: mem.px,
      y: mem.py,
      dist: controlDist,
      tick: tick
    });

    while (mem.path.length > 150) {
      mem.path.shift();
    }
  }

  var noProgress = tick - mem.bestTick;

  if (
    (mem.mode === "go" || mem.mode === "follow") &&
    mem.baseCmd > 0.24 &&
    mem.speedFilt < 0.13 &&
    controlDist > 1.25
  ) {
    mem.stuck += 1;
  } else {
    mem.stuck = Math.max(0, mem.stuck - 2);
  }

  function chooseSide() {
    if (leftOpen > rightOpen + 0.45) {
      return 1;
    }

    if (rightOpen > leftOpen + 0.45) {
      return -1;
    }

    if (
      goalError > 20 &&
      leftOpen > 0.80 &&
      leftOpen > rightOpen - 0.15
    ) {
      return 1;
    }

    if (
      goalError < -20 &&
      rightOpen > 0.80 &&
      rightOpen > leftOpen - 0.15
    ) {
      return -1;
    }

    if (rightThreat > leftThreat + 0.16) {
      return 1;
    }

    if (leftThreat > rightThreat + 0.16) {
      return -1;
    }

    if (Math.abs(goalError) > 28) {
      return goalError > 0 ? 1 : -1;
    }

    return mem.lastSide === 1 ? -1 : 1;
  }

  function beginFollow(forceNewSide) {
    if (mem.mode === "follow") {
      return;
    }

    var side = mem.side;

    if (side !== 1 && side !== -1) {
      side = chooseSide();
    } else if (forceNewSide) {
      side = chooseSide();
    } else {
      var selected = pathOpen(side);
      var opposite = pathOpen(-side);

      if (
        selected < 0.66 &&
        opposite > selected + 0.34
      ) {
        side = -side;
      }
    }

    if (side !== 1 && side !== -1) {
      side = mem.lastSide === 1 ? -1 : 1;
    }

    mem.mode = "follow";
    mem.side = side;
    mem.lastSide = side;
    mem.followTicks = 0;
    mem.clearTicks = 0;
    mem.blockedTicks = 0;
    mem.sideSwitches = 0;
    mem.lastSideSwitch = tick;
    mem.entryDist = controlDist;

    mem.hitX = mem.px;
    mem.hitY = mem.py;
    mem.hitGoalX = gx;
    mem.hitGoalY = gy;
  }

  function pickRecoveryDirection(reason) {
    var direction = 1;

    if (reason === "panic") {
      if (leftOpen > rightOpen + 0.25) {
        direction = 1;
      } else if (rightOpen > leftOpen + 0.25) {
        direction = -1;
      } else if (Math.abs(goalError) > 30) {
        direction = goalError > 0 ? 1 : -1;
      } else {
        direction = mem.side === 1 ? -1 : 1;
      }
    } else if (mem.side === 1 || mem.side === -1) {
      direction = -mem.side;

      if (
        pathOpen(direction) < 0.55 &&
        pathOpen(-direction) > pathOpen(direction) + 0.15
      ) {
        direction = -direction;
      }
    } else {
      direction = chooseSide();
    }

    if (direction !== 1 && direction !== -1) {
      direction = mem.lastSide === 1 ? -1 : 1;
    }

    return direction;
  }

  function beginRecovery(direction, reason) {
    if (mem.mode === "recover") {
      return;
    }

    if (direction !== 1 && direction !== -1) {
      direction = pickRecoveryDirection(reason || "recovery");
    }

    var veryTight =
      frontDist < 1.65 &&
      leftOpen < 1.55 &&
      rightOpen < 1.55;

    mem.mode = "recover";
    mem.recoverDir = direction;
    mem.lastSide = direction;
    mem.recoverPhase = 0;
    mem.recoverTicks = 0;
    mem.recoverStartHeading = effectiveHeading;
    mem.recoverAngle = veryTight ? 135 : 92;
    mem.recoverReverse = veryTight ? 13 : 10;
    mem.recoverSwitched = false;
    mem.recoverReason = reason || "recovery";
    mem.recoverCount += 1;

    mem.followTicks = 0;
    mem.clearTicks = 0;
    mem.blockedTicks = 0;
    mem.sideSwitches = 0;

    mem.bestDist = controlDist;
    mem.bestTick = tick;
    mem.stuck = 0;
    mem.loopHits = 0;
    mem.path = [];
    mem.cooldown = 220;
  }

  if (mem.mode === "follow") {
    var currentSide =
      mem.side === 1 || mem.side === -1
        ? mem.side
        : chooseSide();

    var preSelected = pathOpen(currentSide);
    var preOpposite = pathOpen(-currentSide);

    if (
      frontDist < 1.38 &&
      preSelected < 0.90
    ) {
      mem.blockedTicks += 1;
    } else {
      mem.blockedTicks =
        Math.max(0, mem.blockedTicks - 2);
    }

    if (
      frontDist < 1.10 &&
      preSelected < 0.68 &&
      preOpposite < 0.68
    ) {
      mem.blockedTicks += 2;
    }
  } else {
    mem.blockedTicks = 0;
  }

  var recoveryWanted =
    (
      mem.stuck > 55 &&
      controlDist > 1.30 &&
      mem.baseCmd > 0.20
    ) ||
    (
      mem.cooldown <= 0 &&
      controlDist > 1.55 &&
      noProgress > 320 &&
      (
        mem.mode === "follow" ||
        mem.speedFilt < 0.36
      )
    ) ||
    (
      mem.mode === "follow" &&
      mem.followTicks > 220 &&
      noProgress > 180
    ) ||
    (
      repeatedPosition &&
      mem.loopHits >= 1 &&
      noProgress > 55
    );

  if (
    mem.mode === "go" ||
    mem.mode === "follow"
  ) {
    if (
      panic ||
      (
        boxed &&
        controlDist > 1.05
      )
    ) {
      beginRecovery(
        pickRecoveryDirection("panic"),
        "panic"
      );
    } else if (
      mem.mode === "follow" &&
      mem.blockedTicks > 34 &&
      controlDist > 1.20
    ) {
      beginRecovery(
        pickRecoveryDirection("blocked"),
        "blocked"
      );
    } else if (
      recoveryWanted &&
      controlDist > 1.25
    ) {
      beginRecovery(
        pickRecoveryDirection("no-progress"),
        "no-progress"
      );
    } else if (
      mem.mode === "go" &&
      obstacleAhead
    ) {
      beginFollow(false);
    }
  }

  if (mem.mode === "recover") {
    if (mem.recoverPhase === 0) {
      mem.recoverTicks += 1;

      if (mem.recoverTicks <= mem.recoverReverse) {
        return drive(-0.30, 0, true);
      }

      mem.recoverPhase = 1;
      mem.recoverTicks = 0;
      mem.recoverStartHeading = effectiveHeading;
    }

    if (mem.recoverPhase === 1) {
      var pivotTicks = mem.recoverTicks;
      var rd = mem.recoverDir;

      if (
        pivotTicks > 8 &&
        !mem.recoverSwitched &&
        pathOpen(rd) < 0.64 &&
        pathOpen(-rd) > pathOpen(rd) + 0.34
      ) {
        rd = -rd;
        mem.recoverDir = rd;
        mem.lastSide = rd;
        mem.recoverSwitched = true;
        mem.recoverStartHeading = effectiveHeading;
        mem.recoverAngle = Math.min(
          mem.recoverAngle,
          105
        );
      }

      var turned =
        rd * wrapDeg(
          effectiveHeading - mem.recoverStartHeading
        );

      if (
        pivotTicks < 8 ||
        (
          turned < mem.recoverAngle &&
          pivotTicks < 72
        )
      ) {
        mem.recoverTicks += 1;
        return drive(0, rd * 0.44, true);
      }

      mem.recoverPhase = 2;
      mem.recoverTicks = 0;
    }

    if (mem.recoverPhase === 2) {
      if (mem.recoverTicks < 9) {
        mem.recoverTicks += 1;
        return drive(
          0.12,
          mem.recoverDir * 0.16,
          true
        );
      }

      mem.mode = "follow";
      mem.side = mem.recoverDir;
      mem.lastSide = mem.recoverDir;
      mem.followTicks = 0;
      mem.clearTicks = 0;
      mem.blockedTicks = 0;
      mem.sideSwitches = 0;
      mem.lastSideSwitch = tick;
      mem.entryDist = controlDist;
      mem.hitX = mem.px;
      mem.hitY = mem.py;
      mem.hitGoalX = gx;
      mem.hitGoalY = gy;

      return drive(
        0.14,
        mem.recoverDir * 0.13,
        true
      );
    }
  }

  if (mem.mode === "follow") {
    mem.followTicks += 1;

    var side = mem.side === 1 || mem.side === -1
      ? mem.side
      : chooseSide();

    var selectedPath = pathOpen(side);
    var oppositePath = pathOpen(-side);

    if (
      mem.followTicks > 10 &&
      tick - mem.lastSideSwitch > 55 &&
      selectedPath < 0.72 &&
      oppositePath > selectedPath + 0.32
    ) {
      side = -side;
      mem.side = side;
      mem.lastSide = side;
      mem.sideSwitches += 1;
      mem.lastSideSwitch = tick;

      selectedPath = pathOpen(side);
      oppositePath = pathOpen(-side);
    }

    if (
      mem.followTicks > 5 &&
      frontDist < 1.65 &&
      selectedPath < 0.84 &&
      oppositePath > selectedPath + 0.20 &&
      tick - mem.lastSideSwitch > 25
    ) {
      side = -side;
      mem.side = side;
      mem.lastSide = side;
      mem.sideSwitches += 1;
      mem.lastSideSwitch = tick;

      selectedPath = pathOpen(side);
      oppositePath = pathOpen(-side);
    }

    if (
      frontDist < 1.10 &&
      selectedPath < 0.66 &&
      oppositePath < 0.66
    ) {
      beginRecovery(-side, "blocked");
      return drive(-0.23, 0, true);
    }

    var inner =
      side > 0 ? ray[1] : ray[3];

    var outer =
      side > 0 ? ray[0] : ray[4];

    var wallSeen =
      inner < 4.6 || outer < 4.6;

    var wallTerm = 0;

    if (inner < 0.70) {
      wallTerm = side * 0.42;
    } else if (inner < 1.25) {
      wallTerm = side * clamp(
        (1.18 - inner) * 0.45,
        0,
        0.27
      );
    } else if (
      wallSeen &&
      inner > 2.0
    ) {
      wallTerm = -side * clamp(
        (inner - 2.0) * 0.075,
        0,
        0.16
      );
    }

    var frontTerm = 0;

    if (frontDist < 4.8) {
      frontTerm = clamp(
        0.10 + (4.8 - frontDist) * 0.30,
        0.10,
        0.78
      );
    }

    var commitTerm =
      frontDist < 4.5 && mem.followTicks < 22
        ? 0.045
        : 0;

    var goalTerm = 0;

    if (frontDist > 2.65) {
      goalTerm = clamp(
        goalError * 0.0035,
        -0.25,
        0.25
      );
    } else {
      goalTerm = clamp(
        goalError * 0.00055,
        -0.055,
        0.055
      );
    }

    var followTurn =
      side * (frontTerm + commitTerm) +
      wallTerm +
      0.78 * (rightThreat - leftThreat) +
      goalTerm -
      0.00045 * clamp(mem.headingRate, -200, 200) +
      boundaryTurn * 0.55;

    if (
      frontDist < 1.38 &&
      selectedPath > 0.66 &&
      followTurn * side < 0.20
    ) {
      followTurn = side * 0.20;
    }

    followTurn = clamp(followTurn, -0.72, 0.72);

    var followBase;

    if (frontDist < 0.70) {
      followBase = 0;
    } else if (frontDist < 1.05) {
      followBase = 0.025;
    } else if (frontDist < 1.45) {
      followBase = 0.075;
    } else if (frontDist < 2.00) {
      followBase = 0.15;
    } else if (frontDist < 2.75) {
      followBase = 0.27;
